INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 29, 'theory', 'Quiz: Reading a big project');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 29, 0, 'Which git grep option shows not only the matching line but the whole function around it?', '["-n", "-W", "--heading", "--and"]', 1, '-W (--function-context) shows the text from the line with the function name to the next function. -n only adds line numbers, --heading puts the file name on its own line, and --and joins patterns.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 29, 1, 'What does git log -S''kvm_cpu_exec'' find?', '["Every commit whose message contains the string", "Every commit that touched a file with that name", "Only the commits that added the string for the first time", "Commits that changed how many times the string occurs in the files"]', 3, '-S searches the content of changes: a commit is listed if the number of occurrences differs before and after it. So additions, removals and renames all appear. Searching messages is --grep.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 29, 2, 'In perf report a function has Self 2% and Children 80%. What does it mean?', '["The function itself spends little time, but 80% of the samples pass through it: the time goes to the functions it calls", "The function is called in 2% of cases", "78% of the samples with this function were lost", "The function makes up 2% of the program code"]', 0, 'Self is the time in the function itself, Children is the time in it and everything it called. A big Children with a small Self points to the callees, and those are what you read.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 29, 3, 'In ps -T output of a QEMU process you see a thread named ''CPU 1/KVM''. What is it and what does it most likely do?', '["A kernel thread that saves the guest state to disk", "The monitor thread that accepts QMP commands", "The thread of virtual CPU number 1: it calls ioctl KVM_RUN in a loop", "A thread-pool worker that runs blocking jobs"]', 2, 'QEMU names a virtual CPU thread this way in kvm_start_vcpu_thread, and it runs kvm_cpu_exec with the ioctl KVM_RUN (QEMU 11.1). The monitor and workers are named differently: IO mon_iothread and worker.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 29, 4, 'A line of a tags file has the field ''file:'' with an empty value. What does it mean?', '["The symbol is defined in a header file", "The symbol is static: it is visible only in its own file", "The file with the symbol was deleted from the repository", "The address of the symbol is a line number, not a pattern"]', 1, 'In the tags format description the field file: marks a static (local) tag whose scope is one file; with an empty value it is the file of the line itself. This is how ctags tells apart same-named static functions of different files.');
